"""Render paired reference/YOLO/center-point results and count-only controls."""
import json,html,hashlib,statistics
from pathlib import Path
root=Path('.data/ml/counting63-instance-v1');out=root/'comparison';r=json.loads((out/'comparison-report.json').read_text())
annotations=json.loads((root/'dataset/annotations.json').read_text());train=[x['count'] for x in annotations['images'] if x['split']=='train'];test=[x for x in annotations['images'] if x['split']=='test']
median=round(statistics.median(train));controls={}
for name,value in [('always_zero',0),('always_training_median',median)]:
    errors=[abs(x['count']-value) for x in test];controls[name]={'count':value,'MAE':sum(errors)/len(errors),'exact_rate':sum(e==0 for e in errors)/len(errors)}
r['count_only_controls_not_localizers']=controls
r['evaluation_cautions']=['Reference annotations created by Codex; not independently verified by dermatologist or user','Author has seen previous proxy-model results on these image IDs; this is not a blinded independent clinical test','Annotations are frozen before current training; model predictions never converted into reference labels','15 images have zero countable targets under conservative visual review; this does not diagnose healthy skin','Tiny/unclear/confluent annotation decisions remain subjective; approximate boxes are not masks','This compares single runs of two training pipelines; no clinical accuracy or architecture superiority claim']
r['weight_sha256']={'yolo':hashlib.sha256((out/'yolo/weights/best.pt').read_bytes()).hexdigest(),'point':hashlib.sha256((out/'point-best.pt').read_bytes()).hexdigest()}
(out/'comparison-report.json').write_text(json.dumps(r,indent=2),encoding='utf-8')
y={x['id']:x for x in r['yolo']['per_image']};p={x['id']:x for x in r['point']['per_image']};cards=[]
for t in test:
    i=t['id'];name=f'{i:03}.jpg';ny=len(y[i]['predicted_points']);np=len(p[i]['predicted_points'])
    cards.append(f'<article data-id="{i}"><h2>Ảnh #{i} · tham chiếu {t["count"]} · YOLO {ny} ({ny-t["count"]:+}) · điểm tâm {np} ({np-t["count"]:+})</h2><p>{html.escape(t["note"])}</p><div class="images"><figure><figcaption>Nhãn làm việc: {t["count"]}</figcaption><img src="../overlays/{name}"></figure><figure><figcaption>YOLO: {ny}</figcaption><img src="yolo_test/{name}"></figure><figure><figcaption>Model điểm tâm: {np}</figcaption><img src="point_test/{name}"></figure></div></article>')
table='<table><tr><th>Chỉ số test</th><th>YOLO</th><th>Điểm tâm</th></tr>'
for title,key,fmt in [('MAE (nốt/ảnh)','MAE','.2f'),('RMSE','RMSE','.2f'),('Đúng hoàn toàn','exact_rate','.0%'),('Lệch không quá 1','within_1','.0%'),('Lệch không quá 2','within_2','.0%'),('Precision vị trí','point_precision','.1%'),('Recall vị trí','point_recall','.1%'),('F1 vị trí','point_F1','.1%'),('Tổng dự đoán','predicted_total','d')]:
    table+=f'<tr><td>{title}</td><td>{format(r["yolo"]["test"][key],fmt)}</td><td>{format(r["point"]["test"][key],fmt)}</td></tr>'
table+='</table>'
page='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>So sánh YOLO và model điểm tâm — 63 ảnh</title><style>body{font:16px system-ui;background:#f2f6fa;color:#16324a;margin:24px}main{max-width:1600px;margin:auto}.notice{background:#fff0c7;padding:18px;border-radius:12px}table{border-collapse:collapse;background:white;margin:20px 0}td,th{padding:10px 24px;border:1px solid #cad5df;text-align:left}article{padding:18px;background:white;border-radius:12px;margin:24px 0}.images{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}figure{margin:0}img{width:100%;max-width:512px}figcaption{font-weight:bold;padding:8px 0}pre{white-space:pre-wrap}button,select{font:inherit;padding:8px}@media(max-width:850px){.images{grid-template-columns:1fr}}</style><main><h1>YOLO baseline và model điểm tâm</h1><div class="notice">Nhãn từng đối tượng do Codex rà trực quan: chưa được bác sĩ/người dùng xác nhận độc lập. Đây là thử nghiệm trên nhãn làm việc, chưa chứng minh đếm chính xác lâm sàng. Giữ nguyên 63 ảnh; 45 train / 8 validation / 10 test. 11 ảnh trước thiếu nhãn đã bổ sung vào train. Cùng test IDs và điểm tham chiếu cho cả hai model. Kích thước đầu vào 512; bán kính ghép điểm 16 pixel tại 512. Test không dùng chọn ngưỡng.</div>'''
page+=table+f'<p>Confidence YOLO {r["yolo"]["threshold"]}, điểm tâm {r["point"]["threshold"]}, chọn trên validation. Chênh MAE (điểm tâm − YOLO): {r["paired_MAE_point_minus_yolo"]:.2f}; khoảng bootstrap mô tả 95%: {r["paired_bootstrap_95_percentile_interval"]}.</p>'
page+=f'<p>Đối chứng không nhìn ảnh: luôn dự đoán 0 có MAE {controls["always_zero"]["MAE"]:.2f}; luôn dự đoán trung vị train ({median}) có MAE {controls["always_training_median"]["MAE"]:.2f}. Các đối chứng này không định vị được nốt.</p>'
page+='<p><label>Xem ảnh <select id="filter"><option value="all">Tất cả 10 ảnh test</option>'+''.join(f'<option value="{t["id"]}">#{t["id"]}</option>' for t in test)+'</select></label></p>'+''.join(cards)
page+='<details><summary>Báo cáo JSON đầy đủ</summary><pre>'+html.escape(json.dumps(r,ensure_ascii=False,indent=2))+'</pre></details></main><script>document.getElementById("filter").onchange=e=>document.querySelectorAll("article").forEach(a=>a.hidden=e.target.value!=="all"&&a.dataset.id!==e.target.value);</script></html>'
(out/'index.html').write_text(page,encoding='utf-8');print(json.dumps({'controls':controls,'weights':r['weight_sha256']},indent=2))
